// MARK: Upstream Models/Stream.swift
//
//  Stream.swift
//  YouTubeKit
//
//  Created by Alexander Eichhorn on 06.09.21.
//

import Foundation

@available(iOS 13.0, watchOS 6.0, tvOS 13.0, macOS 10.15, *)
public struct Stream: Sendable {

    public let url: URL
    public let itag: ITag
    public let videoCodec: VideoCodec?
    public let audioCodec: AudioCodec?

    public let fileExtension: FileExtension

    public let bitrate: Int?
    public let averageBitrate: Int?

    @available(*, deprecated, message: "Might be empty if using remote fetching method. Use `videoCodec`, `audioCodec` or `fileExtension` instead.")
    public let mimeType: String

    @available(*, deprecated, message: "Might be empty if using remote fetching method. Use `videoCodec`, `audioCodec` or `fileExtension` instead.")
    public let type: String

    @available(*, deprecated, message: "Might be empty if using remote fetching method. Use `videoCodec`, `audioCodec` or `fileExtension` instead.")
    public let subtype: String

    private let filesize: Int?

    init(format: InnerTube.StreamingData.Format) throws {
        guard let url = format.url.flatMap({ URL(string: $0) }),
              let itag = ITag(format.itag) else {
            throw YouTubeKitError.extractError
        }

        self.url = url
        self.itag = itag

        let codecs: [String]
        (self.mimeType, codecs) = try Extraction.mimeTypeCodec(format.mimeType)

        let mimeTypeComponents = self.mimeType.components(separatedBy: "/")
        self.type = mimeTypeComponents.first ?? ""
        self.subtype = mimeTypeComponents[safe: 1] ?? ""

        self.fileExtension = FileExtension(mimeType: self.mimeType)

        // codec decoding
        if codecs.count >= 2 {
            self.videoCodec = VideoCodec(rawValue: codecs[0])
            self.audioCodec = AudioCodec(rawValue: codecs[1])
        } else if let codec = codecs.first {
            if self.type == "audio" {
                self.audioCodec = AudioCodec(rawValue: codec)
                self.videoCodec = nil
            } else {
                self.videoCodec = VideoCodec(rawValue: codec)
                self.audioCodec = nil
            }
        } else {
            throw YouTubeKitError.extractError
        }

        self.bitrate = format.bitrate
        self.averageBitrate = format.averageBitrate
        self.filesize = format.contentLength.flatMap { Int($0) }
    }

    /// whether the stream is DASH
    public var isAdaptive: Bool {
        videoCodec == nil || audioCodec == nil
    }

    /// video and audio in same stream
    /// opposite of adaptive (is not DASH)
    public var isProgressive: Bool {
        !isAdaptive
    }

    public var isDash: Bool {
        itag.isDash
    }

    /// Whether the stream only contains audio.
    public var includesAudioTrack: Bool {
        audioCodec != nil
    }

    /// Whether the stream only contains video.
    public var includesVideoTrack: Bool {
        videoCodec != nil
    }

    /// Whether the stream contains both audio and video tracks.
    /// - note: alias of `isProgressive`
    @inlinable public var includesVideoAndAudioTrack: Bool {
        isProgressive
    }

    /// Whether the stream can be played inside the native `AVPlayer`
    public var isNativelyPlayable: Bool {
        (videoCodec?.isNativelyPlayable ?? true) && (audioCodec?.isNativelyPlayable ?? true)
    }

    /// smaller pixel size of resolution (e.g. 1080 for 1080p)
    /// - note: is nil, if no video available
    public var videoResolution: Int? {
        itag.videoResolution
    }

}


// MARK: Upstream Models/StreamQuery.swift
//
//  StreamQuery.swift
//  YouTubeKit
//
//  Created by Alexander Eichhorn on 04.09.21.
//

import Foundation

@available(iOS 13.0, watchOS 6.0, tvOS 13.0, macOS 10.15, *)
public extension Collection where Element == Stream {

    func sorted<T: Comparable>(by keyPath: KeyPath<Stream, T>, ascending: Bool = true) -> [Stream] {
        if ascending {
            return sorted { a, b in
                return a[keyPath: keyPath] < b[keyPath: keyPath]
            }
        } else {
            return sorted { a, b in
                return a[keyPath: keyPath] > b[keyPath: keyPath]
            }
        }
    }

    func stream(withITag itag: Int) -> Stream? {
        first(where: { $0.itag.itag == itag })
    }

    func streams(withExactResolution resolution: Int) -> [Stream] {
        filter { $0.itag.videoResolution == resolution }
    }

    func filter(byResolution resolution: (Int?) -> Bool) -> [Stream] {
        filter { resolution($0.itag.videoResolution) }
    }

    /// get stream with lowest video resolution
    func lowestResolutionStream() -> Stream? {
        min(byProperty: { $0.itag.videoResolution ?? .max })
    }

    /// get stream with highest video resolution
    func highestResolutionStream() -> Stream? {
        max(byProperty: { $0.itag.videoResolution ?? 0 })
    }

    /// get stream with lowest audio bitrate
    /// - note: potentially returns stream without audio if none exist
    func lowestAudioBitrateStream() -> Stream? {
        min(byProperty: { $0.itag.audioBitrate ?? .max })
    }

    /// get stream with highest audio bitrate
    /// - note: potentially returns stream without audio if none exist
    func highestAudioBitrateStream() -> Stream? {
        max(byProperty: { $0.itag.audioBitrate ?? 0 })
    }

    /// only returns streams which contain audio, but no video
    func filterAudioOnly() -> [Stream] {
        filter { $0.includesAudioTrack && !$0.includesVideoTrack }
    }

    /// only returns streams which contain video, but no audio
    func filterVideoOnly() -> [Stream] {
        filter { $0.includesVideoTrack && !$0.includesAudioTrack }
    }

    /// only returns streams which contain both audio and video
    func filterVideoAndAudio() -> [Stream] {
        filter { $0.includesVideoAndAudioTrack }
    }

}


